import type { CanonicalConcept, Domain, Importance, Level, Resource, Track } from "./lib.ts";

type Seed = {
  id: string;
  name: string;
  aliases?: string[];
  category: Domain;
  importance: Importance;
  level: Level;
  tracks: Track[];
  prerequisites?: string[];
  technologies?: string[];
  onSpine?: boolean;
  spineOrder?: number;
  resources?: Resource[];
  whyLearn?: string;
  whatToBuild?: string;
  description?: string;
};

function d(category: Domain, name: string): string {
  const templates: Partial<Record<Domain, string>> = {
    FOUNDATIONS: `Build a durable mental model of ${name} so later backend, cloud, and systems topics have a shared vocabulary.`,
    PROGRAMMING: `Develop practical fluency with ${name} to implement services, automate workflows, and reason about code quality.`,
    COMPUTER_SCIENCE: `Understand ${name} as a core CS building block that shapes performance, correctness, and algorithm choice.`,
    NETWORKING: `Learn how ${name} enables machines to find each other, exchange messages, and fail gracefully across networks.`,
    BACKEND: `Apply ${name} when designing server-side systems that expose capabilities, enforce rules, and protect data.`,
    DATABASES: `Use ${name} to store, query, and evolve data with the right consistency, durability, and access patterns.`,
    API_DESIGN: `Design ${name} so clients can integrate reliably—clear contracts, predictable errors, and versioned evolution.`,
    FRONTEND: `Connect ${name} to full-stack delivery so APIs, auth, and UX concerns stay coherent across the stack.`,
    FULL_STACK: `Integrate ${name} across client and server boundaries to ship end-to-end features confidently.`,
    DEVOPS: `Operationalize ${name} to ship changes safely, repeatedly, and with fast feedback from production.`,
    CLOUD: `Map ${name} onto cloud primitives so you can choose managed services without losing architectural clarity.`,
    INFRASTRUCTURE: `Express ${name} as reproducible infrastructure so environments are reviewable, recoverable, and consistent.`,
    CONTAINERS: `Package and isolate workloads with ${name} so runtime behavior is portable across machines and clouds.`,
    ORCHESTRATION: `Schedule and heal containerized services using ${name} so production systems stay declarative and resilient.`,
    SOFTWARE_ARCHITECTURE: `Use ${name} to structure systems around change: boundaries, coupling, and long-term evolvability.`,
    DISTRIBUTED_SYSTEMS: `Reason about ${name} when work spans multiple machines—partial failure, coordination, and trade-offs.`,
    RELIABILITY: `Apply ${name} to keep user-visible promises under failure, load, and change.`,
    SECURITY: `Threat-model and harden systems with ${name} so confidentiality, integrity, and availability hold in practice.`,
    OBSERVABILITY: `Instrument systems with ${name} so you can explain behavior from signals rather than guesswork.`,
    SYSTEM_DESIGN: `Practice ${name} by turning ambiguous product requirements into capacity plans, APIs, and trade-off narratives.`,
    PERFORMANCE: `Measure and improve ${name} with profiles, budgets, and bottleneck-driven changes—not premature micro-optimizations.`,
    DATA_ENGINEERING: `Move and transform data with ${name} when analytics or async pipelines sit beside online request paths.`,
    ADVANCED_ARCHITECTURE: `Evaluate ${name} for complex domains where multi-region, multi-tenant, or platform constraints dominate.`,
  };
  return templates[category] || `Learn ${name} as part of a modern engineering curriculum spanning backend, cloud, and systems.`;
}

