export function buildOntology(): CanonicalConcept[] {
  return SEEDS.map((s) => ({
    id: s.id,
    canonicalName: s.name,
    aliases: Array.from(new Set([s.name, ...(s.aliases || [])].map((a) => a.toLowerCase()))),
    category: s.category,
    description: s.description || d(s.category, s.name),
    prerequisites: s.prerequisites || [],
    sources: [],
    confidence: 0,
    tracks: s.tracks,
    importance: s.importance,
    level: s.level,
    resources: s.resources || [],
    technologies: s.technologies,
    whyLearn:
      s.whyLearn ||
      `This sits on the path from foundations to production systems and unlocks adjacent topics in ${s.tracks.slice(0, 3).join(", ")}.`,
    whatToBuild:
      s.whatToBuild ||
      `Build a small artifact that forces contact with ${s.name}: a demo, lab, or design write-up with measurable outcomes.`,
    onSpine: s.onSpine,
    spineOrder: s.spineOrder,
  }));
}

export function ontologyAliasIndex(concepts: CanonicalConcept[]): Map<string, string> {
  const map = new Map<string, string>();
  for (const c of concepts) {
    map.set(c.id, c.id);
    for (const a of c.aliases) {
      map.set(a.toLowerCase(), c.id);
      map.set(a.toLowerCase().replace(/[^a-z0-9]+/g, " ").trim(), c.id);
    }
    map.set(c.canonicalName.toLowerCase(), c.id);
  }
  return map;
}
